story_summaries.content:
{
 "one_line": "散修白曦凭租赁灵根与黄档闯入凌霄账法，把三十人活埋的自燃认定拆成填桩销骸黑账，于梓库总版刻下读法后踏阶出闸。",
 "acts": [
  {
   "act": 1,
   "span": "1-30章",
   "what_happens": "白曦持黄档入终选，被派九号地基接阎平遗账。他以酉亥时辰矛盾拆穿自燃伪案，坐实填桩销骸与改账，并由代下实授安全员，背上全责死格。",
   "end_state": "实授档级下的安全员，黄档与告诫清销，月俸铺位兑现，全责死格与未结浇桩仍压在名下。"
  },
  {
   "act": 2,
   "span": "31-70章",
   "what_happens": "白曦亲见回收件落桩销号，转入账房勾稽，查出自身法骸押册三百八十毫。会核唱出六处正册为病、底册为注，结包之责锁在经办，押册旋被陌生堂号转走。",
   "end_state": "经办栏锁死结包之责，自身三百八十毫押册已被转包，人在账房与地基之间，真账只在底册。"
  },
  {
   "act": 3,
   "span": "71-110章",
   "what_happens": "白曦以纸角月牙痕串起七份文书，坐实自己是被采买的货。功德正册改以功分计命，一命仅值肆分。会核点他的悬案附页为首件，营建议结与候调先核两呈同挂。",
   "end_state": "协办身份随审候问，首件却是针对自己的悬案附页，两呈挂起，挪格之押已写进呈文。"
  },
  {
   "act": 4,
   "span": "111-150章",
   "what_happens": "协办行页在他登船前已书候配，活人与阎平同制挂案。四十九页摹纸收讫后独缺第十二页押样，规程不催。对销堂三同合式，备兑销入应收行脚，结存被轧减。",
   "end_state": "第十二页押样落在栏外无人催，对销已落下销字，他有骑缝副联，追不回被并掉的名目。"
  },
  {
   "act": 5,
   "span": "151-180章",
   "what_happens": "升档牒将七件并转总册，白曦第一次以人名而非件号上楼。六件旧档被唱作同源。去处栏限期恰是死期，自填则入格，逾期代填即流绞，他坚持要填核字。",
   "end_state": "死期与去处栏同日，不填即由持册人代填成罪，他拒勾销旧账换品级，把出路押在核字上。"
  },
  {
   "act": 6,
   "span": "181-210章",
   "what_happens": "二十四处押形跨三任不改，他悟出押随座位、不随人手。底册封箱直入库，人隔栏、册不下架。核单上他写编无栏可立，被判源无可立，续俟归名，日计三厘。",
   "end_state": "人在内库栏外，名分俟销列为续俟，并案七件，日计三厘记在名下，去处栏依旧空着。"
  },
  {
   "act": 7,
   "span": "211-255章",
   "what_happens": "代填凭件早于入目，特权本在照编。裴琬亲签核至，核目却空。白曦入梓库对照总版，在空读法刻下皆唱其据，三格阖己页、八据留版，持副联唱讫出闸。",
   "end_state": "空格出闸，立于七级阶上。协办之名讫而难刮，新读法已刻进总版，栏内诸账归位，人已不在格中。"
  }
 ],
 "current_state_at_255": "白曦以空格踏出梓库七级石阶，身在天光下，第七任协办之名已讫却难刮。总版新棱已立，落格之墨皆唱其据。阎平冤案入版、悬案词销、卯十九阖落、押册价定、行录注满。凭件已交验放行，他不再占栏；欠的是栏外仍在浇桩的营建与可代填的持册人，以及裴琬亲签、核目留白的那一笔。",
 "what_must_come_next": [
  "把总版新读法从库心唱到外档与九号地基，拦住照旧浇桩销骸，让阎平真据和卯十九活栏在栏外生效。",
  "抢在持册人之前处理裴琬亲签而核目留白的核至凭件，逼其依新规补核或自陷伪签，防空栏回头套人。",
  "安顿空格之后的生计与身份：灵根、征信、全责不再入死格，并了结黑狗供词与崔珩未轧旧账的栏外后果。"
 ]
}

